<span class="k">if</span> (e <span class="k">instanceof</span> Refund) {
    Refund r = (Refund) e;
    <span class="k">if</span> (r.<span class="f">amount</span>() &gt; <span class="n">0</span>) <span class="f">refund</span>(r.<span class="f">id</span>(), r.<span class="f">amount</span>());
} <span class="k">else</span> <span class="k">if</span> (e <span class="k">instanceof</span> Charge) {
