}
<span class="c">    </span>
<span class="c">// Java 21: one real thread per task, no more pool to tune</span>
<span class="k">try</span> (<span class="k">var</span> exec = Executors.<span class="f">newVirtualThreadPerTaskExecutor</span>()) {
    routes.<span class="f">forEach</span>(r -&gt; exec.<span class="f">submit</span>(() -&gt; gds.<span class="f">search</span>(r)));
